<?php

declare(strict_types = 1);

namespace SineMacula\Laravel\Authentication\Contracts;

/**
 * Capability contract: device model can describe the shape of its key.
 *
 * Optional supplement to a device model. The bearer and refresh paths check a
 * token's `did` claim against the device model's key before querying, so a
 * value the database cannot compare against the key column (for example a
 * non-UUID string against a PostgreSQL `uuid` column) never reaches it and a
 * real database error is never mistaken for an unknown device. Integer keys and
 * keys generated by Laravel's `HasUuids` or `HasUlids` are recognised without
 * this contract; a model whose key has any other format implements it.
 *
 * @author      Ben Carey <bdmc@sinemacula.co.uk>
 * @copyright   2026 Sine Macula Limited
 */
interface ValidatesDeviceKey
{
    /**
     * Whether the value has the shape of this model's primary key. Return
     * `false` for anything the key column cannot hold.
     *
     * @param  mixed  $key
     * @return bool
     */
    public function isValidDeviceKey(mixed $key): bool;
}
